JOIN users pu ON pu.email = v.pe
JOIN gaps pg ON pg.user_id = pu.id AND pg.start_time = (date_trunc('week', LOCALTIMESTAMP) + make_interval(mins => (v.ps)::int))
JOIN users au ON au.email = v.ae
JOIN gaps ag ON ag.user_id = au.id AND ag.start_time = (date_trunc('week', LOCALTIMESTAMP) + make_interval(mins => (v.ast)::int))
WHERE (SELECT go FROM seed_run)

RETURNING id
)
INSERT INTO seed_matches (id) SELECT id FROM ins;
